RSpec.describe Timekeeping::LocalOwner, "a failure injected after the reservation write" do
  # "A failure injected after the reservation write leaves no reservation, operation, outbox row or receipt"
  it "a uniqueness error injected after the reservation write inside a rescuing caller transaction is not retried and leaves nothing" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation
    company = create(:company)
    user = create(:user)
    project = create(:project, client: create(:client, company:))
    entry = Timekeeping::LocalEntry.create!(
      company_id: company.id, user_id: user.id, project_id: project.id, work_date: Date.current,
      duration: 30.0, bill_status: "unbilled"
    )
    version_before = entry.version
    service = described_class::Actor.service(name: "invoice-boundary", company_id: company.id,
                                             operations: %w[reservations.prepare])
    expect(described_class::STEPS).to include(:reservations_written)
    reached = []
    # A RecordNotUnique from anywhere but the receipt insert must never be taken for a receipt
    # another writer committed, or the backstop would retry and commit this write.
    fail_after_reservations = lambda do |step|
      reached << step
      raise ActiveRecord::RecordNotUnique, "injected" if step == :reservations_written
    end
    count = ->(table) { ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM #{table}").to_i }
    tables = %w[reservations invoice_operations service_idempotency_receipts entry_audits entry_outbox_items]
