        operation: :prepare, company_id: company.id, generation: generation.to_s, actor: service,
        params: { "body" => { "invoice_id" => 501, "operation_id" => SecureRandom.uuid, "disposition" => "active",
                              "entries" => [entry.id], "generation" => generation } },
        checkpoint: fail_after_reservations
      )
    rescue ActiveRecord::RecordNotUnique
      raised = true
    end

    expect(raised).to be(true)
    expect(reached.count(:reservations_written)).to eq(1)
    expect(tables.index_with { |table| count.call(table) }).to eq(before)
    expect(entry.reload.version).to eq(version_before)
